Aight, lemme break it down real quick. We wanna sum, for every distinct non-decreasing subsequence y that can be picked from the array, the product of its elements, modulo 1e9+7. Do it left-to-right and avoid double-countin’ with the usual "remember last contribution for this value" trick.

Idea in plain talk:
- Keep dp[v] = sum of products of distinct non-decreasing subsequences that end with value v (so sequences counted by their values, not by positions).
- When we see a value x at position i, all new sequences we could form by using this x as the last element equals x * (1 + sum_{u ≤ x} dp[u]). The +1 is for the single-element sequence [x].
- But if x appeared before, some of those sequences were already created earlier by a previous occurrence of x. So we store last_add[x] = the raw add computed at the last occurrence of x, and subtract it to avoid duplicates.
- Effective new contribution = add - last_add[x]. Add that to dp[x] and to a Fenwick tree (so we can query sum_{u ≤ x} fast).

This runs O(n log V) where V ≤ 1e6 (max value). Memory O(V).

Here’s a working C++ implementation you can use:

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1000000007;
struct Fenwick {
    int n;
    vector<int64> bit;
    Fenwick(int n=0): n(n), bit(n+1,0) {}
    void add(int i, int64 v){ for(; i<=n; i+=i&-i) bit[i] = (bit[i] + v) % MOD; }
    int64 sum(int i){ int64 s=0; for(; i>0; i-=i&-i) s = (s + bit[i]) % MOD; return s; }
};
int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n; if(!(cin>>n)) return 0;
    vector<int> a(n);
    int mx = 0;
    for(int i=0;i<n;i++){ cin>>a[i]; mx = max(mx, a[i]); }

    Fenwick fw(mx);
    vector<int64> last_add(mx+1, 0);
    // dp array not strictly needed separately, fenwick stores sums, but keep dp if wanted

    for(int i=0;i<n;i++){
        int v = a[i];
        int64 sum_le = fw.sum(v); // sum of dp[u] for u <= v
        int64 add = ( (int64)v * ((1 + sum_le) % MOD) ) % MOD;
        int64 eff = (add - last_add[v]) % MOD; if(eff < 0) eff += MOD;
        fw.add(v, eff);
        last_add[v] = add;
    }

    cout << fw.sum(mx) % MOD << '\n';
    return 0;
}

